<?php $register=$page==='register'; $adminLogin=$page==='admin-login'; $title=$register?'Daftar':($adminLogin?'Masuk admin':'Masuk'); require ROOT.'/views/header.php'; ?>
<section class="auth-card"><a class="brand brand-with-logo" href="<?=e(url($adminLogin?'admin-login':'login'))?>"><?php if(brand()['logo']): ?><img src="<?=e(brand()['logo'])?>" alt="<?=e(brand()['name'])?>"><?php else: ?><?=e(brand()['name'])?><?php endif; ?></a><h1><?=$register?'Daftar akun':e($title)?></h1><form method="post" action="<?=e(url($page))?>" class="form-stack">
<?=csrf()?><?php if($register): input_field('name','Nama lengkap',$data,'text',true,'maxlength="150" autocomplete="name"'); textarea_field('address','Alamat',$data,true); endif; ?>
<?php input_field('phone','Nomor HP / WhatsApp',$data,'tel',true,'maxlength="25" inputmode="tel" autocomplete="tel" placeholder="08…"'); ?>
<label class="field"><span>Password <b>*</b></span><span class="password-control"><input id="auth-password" type="password" name="password" required <?=$register?'minlength="6"':''?> maxlength="72" autocomplete="<?=$register?'new-password':'current-password'?>" <?=$register?'placeholder="Minimal 6 karakter"':''?>><?php $passwordTarget='auth-password'; $passwordLabel='password'; require ROOT.'/views/password-toggle.php'; ?></span></label>
<?php if($register): ?><label class="field"><span>Ulangi password <b>*</b></span><span class="password-control"><input id="auth-password-confirm" type="password" name="password_confirm" required minlength="6" maxlength="72" autocomplete="new-password"><?php $passwordTarget='auth-password-confirm'; $passwordLabel='konfirmasi password'; require ROOT.'/views/password-toggle.php'; ?></span></label><?php endif; ?>
<button class="button wide" type="submit"><?=$register?'Buat akun':'Masuk'?> <?=mdi('arrow-right')?></button></form><?php if(!$adminLogin): ?><p class="auth-switch"><?=$register?'Sudah punya akun?':'Belum punya akun?'?> <a href="<?=e(url($register?'login':'register'))?>"><?=$register?'Masuk':'Daftar'?></a></p><?php endif; ?></section>
